contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address owner, address spender, uint256 value, uint256 deadline) public {
        require(deadline < block.timestamp, "must be expired");
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(
                c.permit.selector, owner, spender, value, deadline, uint8(1), bytes32(0), bytes32(0)
            )
        );
        require(!ok, "permit with expired deadline must revert");
        assert(c.allowance(owner, spender) == 0 && c.nonces(owner) == 0);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to) public {
        require(c.totalSupply() == 0);
        uint256 supplyBefore = c.totalSupply();
        bool reverted;
        try c.buyShares(to) { reverted = false; }
        catch { reverted = true; }
        assert(reverted && c.totalSupply() == supplyBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to) public {
        uint256 balBefore = c.balanceOf(to);
        bool reverted;
        uint256 shares;
        try c.buyShares(to) returns (uint256 s, uint256, uint256) {
            reverted = false;
            shares = s;
        } catch {
            reverted = true;
        }
        if (reverted) {
            assert(c.balanceOf(to) == balBefore);
        } else {
            assert(shares > 1000 && c.balanceOf(to) == balBefore + shares);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to) public {
        uint256 balBefore = c.balanceOf(to);
        uint256 supplyBefore = c.totalSupply();
        bool ok;
        uint256 s;
        try c.buyShares(to) returns (uint256 shares, uint256, uint256) {
            ok = true;
            s = shares;
        } catch {
            ok = false;
        }
        assert(
            (!ok && c.balanceOf(to) == balBefore && c.totalSupply() == supplyBefore) ||
            (ok && s > 1000 && c.balanceOf(to) == balBefore + s && c.totalSupply() == s + 1001)
        );
    }
    receive() external payable {}
}

