contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 shareAmount, uint256 timeDelta) public {
        require(timeDelta > 0);
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        uint256 deadline = block.timestamp - timeDelta;
        bool reverted;
        try c.sellShares(shareAmount, address(this), 0, 0, "", deadline) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && c.totalSupply() == supplyBefore && c.balanceOf(address(this)) == balBefore);
    }
    receive() external payable {}
}

